//! Build-time codegen for `spells.json`: dump order kept, rune maps sorted
//! by key like the old reader. A null row renders the old defaults.

/// Render `spells_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "spells");
    let rows = crate::dump_rows(&parsed, "spells");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/spells.json - do not edit.\n\
         pub static ALL: &[super::StaticSpell] = &[\n",
    );
    for row in rows {
        generated.push_str(&format!(
            "    super::StaticSpell {{ spell: \"{}\", name: {}, com: {}, members: {}, level: {}, runes: {}, \
             xp: {}, maxhit: {} }},\n",
            crate::escape_for_rust_literal(row.get("spell").as_str().unwrap_or("")),
            crate::render_opt_str(row.get("name")),
            crate::render_opt_str(row.get("com")),
            row.get("members").as_bool().unwrap_or(false),
            row.get("level").as_i64().unwrap_or(0),
            crate::render_str_int_map(row, "runes"),
            row.get("xp").as_i64().unwrap_or(0),
            match row.get("maxhit").as_i64() {
                Some(value) => format!("Some({value})"),
                None => String::from("None"),
            },
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("spells_generated.rs", &generated);
}
